// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 ethAmount) public {
        // Bound ethAmount to a reasonable range
        ethAmount = bound(ethAmount, 0.001 ether, 10 ether);
        // Seed the market first
        vm.deal(address(this), 1 ether);
        c.seedMarket(1000);

        // Record state before buy
        uint256 claimedBefore = c.claimedDrugs(user);
        uint256 balanceBefore = address(c).balance;

        vm.deal(user, ethAmount);
        vm.prank(user);
        (bool success, ) = address(c).call{value: ethAmount}(abi.encodeWithSignature("buyDrugs()"));

        // Skip if revert (e.g., not initialized but we initialized)
        if (!success) return;

        // Calculate expected drugs
        uint256 expectedDrugs = c.calculateDrugBuy(ethAmount, balanceBefore);
        uint256 devFee = c.devFee(expectedDrugs);
        uint256 expectedIncrease = expectedDrugs - devFee;

        // After buy, user's claimedDrugs should increase by exactly expectedIncrease
        uint256 claimedAfter = c.claimedDrugs(user);
        assertTrue(claimedAfter - claimedBefore == expectedIncrease, "claimedDrugs increase does not match expected amount");
    }
}

